# v41.18: quiz time limit, report filters, question-bank filters, self-rating guard, no demo manager default
import asyncio, os
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
from playwright.async_api import async_playwright
EXE = os.environ.get('CHROME') or (lambda d: d if os.path.exists(d) else None)('/opt/pw-browsers/chromium_headless_shell-1208/chrome-headless-shell-linux64/chrome-headless-shell')
WEB = os.environ.get('SF_WEB', 'public'); RES = []
def ok(n, c, x=''): RES.append((n, bool(c))); print(('PASS ' if c else 'FAIL ') + n, '' if c else str(x)[:300], flush=True)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path=EXE); pg = await b.new_page(viewport={'width':1400,'height':900})
        await pg.add_init_script(path=os.path.join(ROOT, 'tests/e2e/hook.js')); errs = []; pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.goto('file://' + ROOT + '/' + WEB + '/index.html?small=1'); await pg.wait_for_selector('#sf-user')
        S = lambda e: pg.evaluate(f"(() => {{ const s = window.__app.state; return {e}; }})()"); V = lambda e: pg.evaluate(f"(() => {{ const v = window.__app.renderVals(); return {e}; }})()"); W = lambda ms=300: pg.wait_for_timeout(ms)
        await pg.locator('.sf-demo2-b').filter(has_text='Learner').click(); await pg.get_by_role('button', name='Login', exact=True).click(); await W(800)
        qid = await pg.evaluate("window.__app.state.adminCourses.find(c => c.id === 'safety').items.find(i => i.kind === 'quiz').quizId")
        await pg.evaluate(f"window.__app.setState(st => ({{ quizzes: st.quizzes.map(z => z.id === {qid} ? {{ ...z, time: 1 }} : z), itemDone: {{ ...st.itemDone, 'Maya Okafor': {{ ...(st.itemDone['Maya Okafor']||{{}}), safety: {{ 0:'2026-10-01', 1:'2026-10-01', 2:'2026-10-01' }} }} }} }}))")
        qi = await pg.evaluate("window.__app.state.adminCourses.find(c => c.id === 'safety').items.findIndex(i => i.kind === 'quiz')")
        await pg.evaluate(f"window.__app.go('item', {{ courseId:'safety', itemIdx:{qi} }})"); await W(300)
        await pg.evaluate("window.__app.renderVals().startQuiz()"); await W(400)
        ok('timed quiz shows a countdown', await V("v.quizTimed") and await pg.locator('.quiz-timer').count() == 1)
        t1 = await V("v.quizTimeLeft"); await W(2200); t2 = await V("v.quizTimeLeft")
        ok('countdown ticks', t1 != t2 and t2.startswith('0:'), (t1, t2))
        await pg.evaluate("window.__app.setState({ qEndsMs: Date.now() + 500 })"); await W(2500)
        ok('time up hands the attempt in', await S("s.qDone === true && !s.qEndsMs"))
        ok('attempt recorded', await S(f"s.attemptRecs.some(r => r.user === 'Maya Okafor' && r.quizId === {qid})"))
        await pg.evaluate(f"window.__app.setState(st => ({{ quizzes: st.quizzes.map(z => z.id === {qid} ? {{ ...z, time: 0 }} : z), attemptsUsed: {{}} }}))")
        await pg.evaluate(f"window.__app.go('item', {{ courseId:'safety', itemIdx:{qi} }})"); await W(200); await pg.evaluate("window.__app.renderVals().startQuiz()"); await W(300)
        ok('untimed quiz shows no countdown', not await V("v.quizTimed") and await pg.locator('.quiz-timer').count() == 0)
        await pg.evaluate("window.__app.go('reports', { adminView:true, role:'admin', meName:'Lena Fischer', meRole:'admin', repType:'learning' })"); await W(400)
        mg = await V("v.repMgrOptions.map(o => o.v)"); real = await S("[...new Set(s.users.map(u => u.manager).filter(m => m && m !== 'None'))].sort()")
        ok('manager filter lists the real managers', mg == ['All'] + real + ['None'], mg)
        cs = await V("v.repCourseOptions.map(o => o.v)"); ok('course filter lists the real courses', set(cs[1:]) == set(await S("s.adminCourses.map(a => a.title)")))
        ok('learning report: no course / status filters', await V("!v.repF.course && !v.repF.status && v.repF.range && v.repF.user"))
        n0 = await V("v.rep.rowCount"); await pg.evaluate("window.__app.setState({ repStatus:'Completed', repCourse: window.__app.state.adminCourses[0].title })"); await W(200)
        ok('a leftover status / course does not empty this report', await V("v.rep.rowCount") == n0)
        await pg.evaluate("window.__app.setState({ repType:'compliance' })"); await W(200)
        ok('compliance status options are its own', await V("v.repStatusOptions.map(o => o.v).join()") == 'All,Valid,Expiring soon,Expired,Overdue,Not completed')
        ok('no Save report / Schedule email buttons', await pg.get_by_role('button', name='Save report').count() == 0 and await pg.get_by_role('button', name='Schedule email').count() == 0)
        await pg.evaluate("window.__app.setState({ repType:'learning', repStatus:'All', repCourse:'All', repMgr:'None' })"); await W(200)
        nm = await V("v.rep.rowCount"); exp = await S("s.users.filter(u => u.status !== 'Deactivated' && (!u.manager || u.manager === 'None')).length")
        ok('"No manager" matches people without a manager', nm == exp and nm > 0, (nm, exp))
        await pg.evaluate("window.__app.setState({ repMgr:'All' })")
        await pg.evaluate("window.__app.go('qbank', { adminView:true })"); await W(400)
        ok('question bank: 4 filters by default', await pg.locator('.qb-f').count() == 4)
        await pg.get_by_role('button', name='More filters').click(); await W(200)
        ok('More filters opens the rest', await pg.locator('.qb-f').count() == 11)
        await pg.evaluate("window.__app.setState(st => ({ qbMore:false, qf: { ...st.qf, bloom:'Apply' } }))"); await W(200)
        ok('an extra filter in use keeps them open', await pg.locator('.qb-f').count() == 11)
        await pg.evaluate("window.__app.go('users', { adminView:true })"); await W(300)
        await pg.get_by_role('button', name='+ Create account').click(); await pg.get_by_role('menuitem', name='Single account').click(); await W(300)
        ok('new account has no demo manager', await S("(window.__app.renderVals().ud || {}).manager") in ('None', None))
        await pg.evaluate("window.__app.setState(st => ({ userModal:false, ud:null, reviews: [{ id:'rself', learner:'Lena Fischer', quiz:'X', qid: st.qs[0].id, answer:'mine', submitted:'Just now', rating:null, feedback:'' }].concat(st.reviews), rvDraft: { rself: { rating: 1 } } }))")
        await pg.evaluate("window.__app.go('gradebook', { adminView:true, rvTab:'pending' })"); await W(300)
        await pg.evaluate("window.__app.renderVals().rvList.find(r => r.id === 'rself').save()"); await W(200)
        ok('cannot rate own answer', await S("s.reviews.find(r => r.id === 'rself').rating === null") and 'own answer' in (await S("s.toast") or ''))
        # Escape closes the top pop-up like an outside click, but never an editor with typed work
        await pg.evaluate("window.__app.go('users', { adminView:true })"); await W(200)
        await pg.evaluate("window.__app.setState({ uMng: window.__app.state.users[0].id })"); await W(150); await pg.keyboard.press('Escape'); await W(150)
        ok('Escape closes the Manage menu', await pg.locator('.ovl-1').count() == 0)
        await pg.evaluate("window.__app.setState({ assignOpen:true })"); await W(150); await pg.keyboard.press('Escape'); await W(150)
        ok('Escape closes the Assign pop-up', await pg.locator('.ovl-1').count() == 0)
        await pg.get_by_role('button', name='+ Create account').click(); await pg.get_by_role('menuitem', name='Single account').click(); await W(200)
        await pg.locator('.ovl-28 input').first.fill('Half typed'); await pg.keyboard.press('Escape'); await W(150)
        ok('Escape keeps an open account form', await S("!!s.userModal && s.ud.name === 'Half typed'"))
        await pg.evaluate("window.__app.setState({ userModal:false, ud:null })")
        ok('NO JS ERRORS', not errs, errs[:3])
        await b.close()
    print('SUMMARY', sum(c for _, c in RES), '/', len(RES))
asyncio.run(main())
